   525  static gboolean
   526  parse_userinfo (const gchar  *start,
   527                  gsize         length,
   528                  GUriFlags     flags,
   529                  gchar       **user,
   530                  gchar       **password,
   531                  gchar       **auth_params,
   532                  GError      **error)
   533  {
   534    const gchar *user_end = NULL, *password_end = NULL, *auth_params_end;
   535
   536    auth_params_end = start + length;
   537    if (flags & G_URI_FLAGS_HAS_AUTH_PARAMS)
   538      password_end = memchr (start, ';', auth_params_end - start);
   539    if (!password_end)
   540      password_end = auth_params_end;
   541    if (flags & G_URI_FLAGS_HAS_PASSWORD)
   542      user_end = memchr (start, ':', password_end - start);
   543    if (!user_end)
   544      user_end = password_end;
   545
   546    if (!uri_normalize (user, start, user_end - start, flags,
   547                        G_URI_ERROR_BAD_USER, error))
   548      return FALSE;
   549
   550    if (*user_end == ':')
   551      {
   552        start = user_end + 1;
   553        if (!uri_normalize (password, start, password_end - start, flags,
   554                            G_URI_ERROR_BAD_PASSWORD, error))
   555          {
   556            if (user)
   557              g_clear_pointer (user, g_free);
   558            return FALSE;
   559          }
   560      }
   561    else if (password)
   562      *password = NULL;
   563
   564    if (*password_end == ';')
   565      {
   566        start = password_end + 1;
   567        if (!uri_normalize (auth_params, start, auth_params_end - start, flags,
   568                            G_URI_ERROR_BAD_AUTH_PARAMS, error))
   569          {
   570            if (user)
   571              g_clear_pointer (user, g_free);
   572            if (password)
   573              g_clear_pointer (password, g_free);
   574            return FALSE;
   575          }
   576      }
   577    else if (auth_params)
   578      *auth_params = NULL;
   579
   580    return TRUE;
   581  }
