   583  static gchar *
   584  uri_cleanup (const gchar *uri_string)
   585  {
   586    GString *copy;
   587    const gchar *end;
   588
   589    /* Skip leading whitespace */
   590    while (g_ascii_isspace (*uri_string))
   591      uri_string++;
   592
   593    /* Ignore trailing whitespace */
   594    end = uri_string + strlen (uri_string);
   595    while (end > uri_string && g_ascii_isspace (*(end - 1)))
   596      end--;
   597
   598    /* Copy the rest, encoding unencoded spaces and stripping other whitespace */
   599    copy = g_string_sized_new (end - uri_string);
   600    while (uri_string < end)
   601      {
   602        if (*uri_string == ' ')
   603          g_string_append (copy, "%20");
   604        else if (g_ascii_isspace (*uri_string))
   605          ;
   606        else
   607          g_string_append_c (copy, *uri_string);
   608        uri_string++;
   609      }
   610
   611    return g_string_free (copy, FALSE);
   612  }
